import{_ as s,o as a,c as i,a3 as t}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Linux et systemd","description":"Installer, mettre à jour et sauvegarder ATLAS sous Linux.","frontmatter":{"title":"Linux et systemd","description":"Installer, mettre à jour et sauvegarder ATLAS sous Linux."},"headers":[],"relativePath":"fr/projects/atlas/linux.md","filePath":"fr/projects/atlas/linux.md","lastUpdated":1792851046000}'),n={name:"fr/projects/atlas/linux.md"};function r(l,e,o,p,d,u){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="linux-et-systemd" tabindex="-1">Linux et systemd <a class="header-anchor" href="#linux-et-systemd" aria-label="Permalink to &quot;Linux et systemd&quot;">​</a></h1><p>L’installateur Linux, introduit dans ATLAS <strong>0.1.298</strong>, utilise le même serveur combiné que Docker et l’application HA. Administration et Card Editor fonctionnent ensemble ; les plugins externes restent installables séparément. L’<a href="/fr/projects/atlas/frontend">intégration ATLAS Runtime</a> native facultative est également implémentée et vérifiée via un dépôt HACS personnalisé sur Pi 5 et Proxmox.</p><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Prérequis&quot;">​</a></h2><ul><li>Linux avec systemd actif, Node.js 22 ou ultérieur et accès root pour l’installation.</li><li>Un package Linux correspondant à l’architecture CPU, à libc et à l’ABI Node de la cible.</li><li>Trois ports libres : 4176 pour l’application, 4175 et 4174 pour les interfaces internes.</li><li>Assez d’espace pour deux versions du Runtime au moins et les sauvegardes de données.</li></ul><p>La construction prend en charge AMD64 et ARM64 et utilise Debian Bookworm/glibc. Un package Alpine/musl n’est pas interchangeable. La préparation native est également vérifiée sous Raspberry Pi OS / Debian 13.7 Trixie avec glibc sur un Raspberry Pi 4 (<code>aarch64</code>, 4 Go de RAM).</p><p>État des vérifications au 15.10.2026 : Debian 12 AMD64 en LXC et le Pi 4 natif avec Node.js 22.23.3 et ATLAS 0.1.303/0.1.304. Sur le Pi, les 17 tests de l’installateur, l’installation, la mise à jour, le retour à la version précédente, la sauvegarde, le redémarrage du service et la récupération automatique après une mise à jour défaillante réussissent. Les données synthétiques de plugin/projet et la configuration sont conservées. Les ports restaient locaux lors de cette première vérification. Les tests suivants valident accès LAN sur4176, véritable redémarrage du Pi 4, démarrage automatique et récupération persistante de la connexion HA depuis 0.1.305. Les autres distributions et matériels nécessitent une qualification séparée.</p><p>L’installateur utilise le compte système <code>atlas</code>. Il refuse un compte existant avec un autre répertoire personnel ou groupe principal et ne reprend pas silencieusement une autre installation ATLAS.</p><h2 id="preparer-un-package" tabindex="-1">Préparer un package <a class="header-anchor" href="#preparer-un-package" aria-label="Permalink to &quot;Préparer un package&quot;">​</a></h2><p>Sur un hôte Linux avec les dépendances de construction habituelles :</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux:prepare</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>output/linux-runtime</code> contient l’application compilée, les dépendances, le plugin de référence et <code>atlas-linux-runtime.json</code>. Un répertoire de sortie existant n’est pas écrasé.</p><p>Autre méthode, avec Docker hors du LXC cible :</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packaging/linux/Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=local,dest=output/linux-export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>L’export comprend une archive, un manifeste, des sommes de contrôle et le binaire Node avec sa licence provenant de l’image officielle Node. Vérifiez la provenance et les SHA-256 avant utilisation. Utilisez une installation Node compatible ; ne remplacez pas une version existante sans vérification. Conservez les liens symboliques relatifs de <code>node_modules</code> pendant le transfert.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Avec un package vérifié et extrait et une version Node compatible :</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/linux-runtime/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/linux-runtime</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atlas</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4176/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>L’installateur valide le package, l’architecture et les modules natifs, crée une sauvegarde, installe une version séparée et démarre le service. La vérification exige les deux interfaces, la version attendue et la cible de distribution Linux. Aucun service tiers n’est arrêté pour libérer un port occupé.</p><h2 id="donnees-persistantes" tabindex="-1">Données persistantes <a class="header-anchor" href="#donnees-persistantes" aria-label="Permalink to &quot;Données persistantes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chemin</th><th>Contenu</th></tr></thead><tbody><tr><td><code>/opt/atlas/releases/</code></td><td>Versions du Runtime séparées.</td></tr><tr><td><code>/opt/atlas/current</code></td><td>Lien symbolique vers la version actuelle.</td></tr><tr><td><code>/opt/atlas/installation.json</code></td><td>État de l’installation et version précédente.</td></tr><tr><td><code>/var/lib/atlas/</code></td><td>Données, plugins, identité, historique de fichiers et corbeille.</td></tr><tr><td><code>/etc/atlas/atlas.env</code></td><td>Configuration protégée, conservée lors des mises à jour.</td></tr><tr><td><code>/etc/systemd/system/atlas.service</code></td><td>Service géré.</td></tr><tr><td><code>/etc/systemd/system/atlas.service.d/</code></td><td>Compléments systemd locaux.</td></tr><tr><td><code>/var/backups/atlas/</code></td><td>Sauvegardes horodatées.</td></tr></tbody></table><p>Les projets de l’éditeur et une partie de l’Administration résident dans le navigateur. Exportez-les séparément depuis leurs interfaces : une sauvegarde serveur ne capture pas le stockage du navigateur. Conservez l’adresse du navigateur, le chemin des données et l’identité de l’installation lors des mises à jour pour préserver les identifiants chiffrés liés localement. Les données Docker/HA ne sont pas migrées silencieusement.</p><h2 id="mise-a-jour-et-retour-a-la-version-precedente" tabindex="-1">Mise à jour et retour à la version précédente <a class="header-anchor" href="#mise-a-jour-et-retour-a-la-version-precedente" aria-label="Permalink to &quot;Mise à jour et retour à la version précédente&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/nouveau-package/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/nouveau-package</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/atlas/current/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>ATLAS est arrêté et sauvegardé avant la mise à jour. Le fichier d’environnement, les plugins installés et les compléments systemd sont conservés. Le lien actuel change de Runtime. En cas d’échec, le Runtime précédent est rétabli. Une installation précédemment arrêtée reste arrêtée après vérification ; l’activation au démarrage est conservée.</p><p>Le retour change le programme, pas les données utilisateur. De futures migrations de données nécessitent une vérification de rétrocompatibilité distincte. Les anciennes versions et sauvegardes ne sont pas supprimées automatiquement. Utilisez <code>systemctl edit atlas</code> pour vos compléments au lieu de modifier directement le service géré.</p><h2 id="sauvegarde-et-restauration" tabindex="-1">Sauvegarde et restauration <a class="header-anchor" href="#sauvegarde-et-restauration" aria-label="Permalink to &quot;Sauvegarde et restauration&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/atlas/current/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/atlas/current/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>La sauvegarde à service arrêté comprend données, configuration, service, compléments et manifeste d’installation. Un service auparavant actif redémarre ensuite. Les sauvegardes sont réservées à root et peuvent contenir des identifiants. Sauvegardez séparément les chemins externes, clés SSH hors des données ATLAS et projets du navigateur.</p><p>Pour restaurer manuellement, arrêtez ATLAS, sauvegardez à nouveau l’état actuel et restaurez les données/configurations sélectionnées aux chemins d’origine avec les propriétaires appropriés. Conservez l’identité de l’installation, préparez le Runtime correspondant puis vérifiez <code>/health</code>. Copier la sauvegarde sur une autre installation ne déverrouille pas ses secrets locaux. Un snapshot VM/LXC avant installation permet aussi de restaurer l’hôte entier.</p><h2 id="reseau-et-plugins" tabindex="-1">Réseau et plugins <a class="header-anchor" href="#reseau-et-plugins" aria-label="Permalink to &quot;Réseau et plugins&quot;">​</a></h2><p>Depuis ATLAS 0.1.305, l’enregistrement des paramètres de l’administration Linux conserve aussi la connexion HA mémorisée sur le serveur avec AES-GCM. La restauration après redémarrage du service ou de l’hôte fonctionne donc en HTTP sur le réseau local sans Web Crypto dans le navigateur. Après la mise à jour, saisissez une fois le jeton existant dans l’administration puis enregistrez ; les versions précédentes peuvent l’avoir conservé uniquement en mémoire.</p><p>Le fichier chiffré <code>admin-connection.enc.json</code> et la clé privée <code>admin-connection.enc.json.key</code> se trouvent à côté de <code>admin-device.json</code> dans le répertoire privé des données ATLAS. Les fichiers utilisent le mode Linux <code>0600</code> ; les données sont liées à l’identité de l’installation. Une sauvegarde complète doit conserver ces trois fichiers et rester confidentielle. Copier uniquement le répertoire du programme ou l’export du navigateur n’inclut pas cette clé. « Oublier le jeton » retire aussi le jeton HA mémorisé du serveur. Des données chiffrées illisibles ne sont pas remplacées automatiquement.</p><p>Toutes les interfaces utilisent loopback par défaut ; Terminal est désactivé. L’installateur n’ouvre aucun pare-feu. L’administrateur peut modifier délibérément <code>ATLAS_APP_HOST</code> pour le LAN et limiter cet accès ; les ports internes restent locaux. L’Administration ne doit pas être exposée sans protection sur Internet.</p><p>File Studio nécessite des permissions Linux correspondant aux chemins approuvés. Les fichiers HA situés sur un autre hôte ne sont pas montés automatiquement. SSH et Oh My Posh pour le Terminal externe sont des prérequis supplémentaires facultatifs, non inclus dans le package Linux.</p><h2 id="perimetre-des-tests" tabindex="-1">Périmètre des tests <a class="header-anchor" href="#perimetre-des-tests" aria-label="Permalink to &quot;Périmètre des tests&quot;">​</a></h2><p>Les régressions utilisent des données temporaires pour vérifier conservation, sauvegarde, échec de mise à jour, retour de version, état du service, installation sans écrasement et validation des chemins/ABI. Un test conteneur avec service simulé ne remplace pas un test systemd natif. Les preuves natives et plateformes ouvertes figurent dans l’<a href="/fr/projects/atlas/development-status">état du développement</a>.</p>`,36)])])}const m=s(n,[["render",r]]);export{h as __pageData,m as default};
